<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kanban Board</title>
  <style>
    :root {
      --bg: #f4f7fb;
      --surface: #ffffff;
      --text: #1f2937;
      --muted: #6b7280;
      --border: #e5e7eb;
      --primary: #4f46e5;
      --primary-dark: #4338ca;
      --todo: #f59e0b;
      --doing: #3b82f6;
      --done: #10b981;
      --shadow: 0 12px 30px rgba(31, 41, 55, 0.08);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      background: var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .app {
      width: min(1200px, calc(100% - 32px));
      margin: 0 auto;
      padding: 48px 0;
    }

    .topbar {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 32px;
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(2rem, 4vw, 3rem);
      letter-spacing: -0.04em;
    }

    .subtitle {
      margin: 0;
      color: var(--muted);
      font-size: 1rem;
    }

    .new-card-form {
      display: flex;
      gap: 10px;
      width: min(100%, 420px);
    }

    #new-card {
      min-width: 0;
      flex: 1;
      padding: 13px 15px;
      border: 1px solid var(--border);
      border-radius: 10px;
      background: var(--surface);
      color: var(--text);
      font: inherit;
      outline: none;
      box-shadow: 0 2px 5px rgba(31, 41, 55, 0.03);
    }

    #new-card:focus {
      border-color: var(--primary);
      box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.14);
    }

    #add-card {
      padding: 13px 18px;
      border: 0;
      border-radius: 10px;
      background: var(--primary);
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: background 0.2s, transform 0.2s;
    }

    #add-card:hover {
      background: var(--primary-dark);
      transform: translateY(-1px);
    }

    .board {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 20px;
      align-items: start;
    }

    .column {
      min-height: 440px;
      padding: 18px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: #eef2f7;
    }

    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 16px;
    }

    .column-title {
      display: flex;
      align-items: center;
      gap: 9px;
      margin: 0;
      font-size: 1.05rem;
    }

    .column-title::before {
      width: 9px;
      height: 9px;
      border-radius: 50%;
      background: var(--todo);
      content: "";
    }

    #col-doing .column-title::before {
      background: var(--doing);
    }

    #col-done .column-title::before {
      background: var(--done);
    }

    .count {
      display: inline-grid;
      min-width: 26px;
      height: 26px;
      padding: 0 7px;
      place-items: center;
      border-radius: 999px;
      background: #dfe5ee;
      color: var(--muted);
      font-size: 0.8rem;
      font-weight: 700;
    }

    .card-container {
      display: flex;
      flex-direction: column;
      gap: 12px;
      min-height: 350px;
    }

    .card {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      padding: 16px;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: var(--surface);
      box-shadow: var(--shadow);
      cursor: grab;
      line-height: 1.45;
      transition: transform 0.2s, box-shadow 0.2s, opacity 0.2s;
    }

    .card:hover {
      transform: translateY(-2px);
      box-shadow: 0 16px 34px rgba(31, 41, 55, 0.12);
    }

    .card:active {
      cursor: grabbing;
    }

    .card.dragging {
      opacity: 0.45;
    }

    .card-title {
      overflow-wrap: anywhere;
    }

    .card-del {
      flex: 0 0 auto;
      width: 28px;
      height: 28px;
      border: 0;
      border-radius: 7px;
      background: transparent;
      color: #9ca3af;
      font-size: 1.1rem;
      line-height: 1;
      cursor: pointer;
    }

    .card-del:hover {
      background: #fee2e2;
      color: #dc2626;
    }

    .column.drag-over {
      background: #e0e7ff;
      outline: 2px dashed var(--primary);
      outline-offset: -2px;
    }

    @media (max-width: 800px) {
      .topbar {
        align-items: stretch;
        flex-direction: column;
      }

      .new-card-form {
        width: 100%;
      }

      .board {
        grid-template-columns: 1fr;
      }

      .column {
        min-height: 240px;
      }

      .card-container {
        min-height: 100px;
      }
    }
  </style>
</head>
<body>
  <main class="app">
    <div class="topbar">
      <div>
        <h1>Project Board</h1>
        <p class="subtitle">Organize your work and keep momentum.</p>
      </div>

      <form class="new-card-form" id="card-form">
        <input id="new-card" type="text" placeholder="Add a new task..." autocomplete="off">
        <button id="add-card" type="submit">Add card</button>
      </form>
    </div>

    <section class="board" aria-label="Kanban board">
      <section class="column" id="col-todo" data-column="todo">
        <header class="column-header">
          <h2 class="column-title">To Do</h2>
          <span class="count" aria-label="To Do card count">0</span>
        </header>
        <div class="card-container" aria-label="To Do cards"></div>
      </section>

      <section class="column" id="col-doing" data-column="doing">
        <header class="column-header">
          <h2 class="column-title">Doing</h2>
          <span class="count" aria-label="Doing card count">0</span>
        </header>
        <div class="card-container" aria-label="Doing cards"></div>
      </section>

      <section class="column" id="col-done" data-column="done">
        <header class="column-header">
          <h2 class="column-title">Done</h2>
          <span class="count" aria-label="Done card count">0</span>
        </header>
        <div class="card-container" aria-label="Done cards"></div>
      </section>
    </section>
  </main>

  <script>
    (() => {
      const storageKey = "kanban-board-state";
      const columns = [...document.querySelectorAll(".column")];
      const form = document.getElementById("card-form");
      const input = document.getElementById("new-card");

      let board = loadBoard();
      let draggedCardId = null;

      function loadBoard() {
        try {
          const saved = JSON.parse(localStorage.getItem(storageKey));
          if (saved && typeof saved === "object") {
            return {
              todo: Array.isArray(saved.todo) ? saved.todo : [],
              doing: Array.isArray(saved.doing) ? saved.doing : [],
              done: Array.isArray(saved.done) ? saved.done : []
            };
          }
        } catch (error) {
          // Ignore invalid saved data and start with an empty board.
        }
        return { todo: [], doing: [], done: [] };
      }

      function saveBoard() {
        localStorage.setItem(storageKey, JSON.stringify(board));
      }

      function render() {
        columns.forEach(column => {
          const columnName = column.dataset.column;
          const container = column.querySelector(".card-container");
          container.replaceChildren();

          board[columnName].forEach(cardData => {
            const card = document.createElement("article");
            card.className = "card";
            card.draggable = true;
            card.dataset.cardId = cardData.id;

            const title = document.createElement("span");
            title.className = "card-title";
            title.textContent = cardData.title;

            const deleteButton = document.createElement("button");
            deleteButton.className = "card-del";
            deleteButton.type = "button";
            deleteButton.setAttribute("aria-label", `Delete ${cardData.title}`);
            deleteButton.textContent = "×";
            deleteButton.addEventListener("click", () => deleteCard(cardData.id));

            card.append(title, deleteButton);
            card.addEventListener("dragstart", event => {
              draggedCardId = cardData.id;
              card.classList.add("dragging");
              event.dataTransfer.effectAllowed = "move";
              event.dataTransfer.setData("text/plain", cardData.id);
            });
            card.addEventListener("dragend", () => {
              draggedCardId = null;
              card.classList.remove("dragging");
              columns.forEach(item => item.classList.remove("drag-over"));
            });

            container.appendChild(card);
          });

          column.querySelector(".count").textContent = board[columnName].length;
        });
      }

      function addCard(title) {
        board.todo.push({
          id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
          title
        });
        saveBoard();
        render();
      }

      function deleteCard(cardId) {
        Object.keys(board).forEach(columnName => {
          board[columnName] = board[columnName].filter(card => card.id !== cardId);
        });
        saveBoard();
        render();
      }

      function moveCard(cardId, destination) {
        let movedCard = null;
        Object.keys(board).forEach(columnName => {
          const index = board[columnName].findIndex(card => card.id === cardId);
          if (index !== -1) {
            movedCard = board[columnName].splice(index, 1)[0];
          }
        });

        if (movedCard) {
          board[destination].push(movedCard);
          saveBoard();
          render();
        }
      }

      form.addEventListener("submit", event => {
        event.preventDefault();
        const title = input.value.trim();
        if (!title) return;
        addCard(title);
        input.value = "";
        input.focus();
      });

      columns.forEach(column => {
        column.addEventListener("dragover", event => {
          event.preventDefault();
          event.dataTransfer.dropEffect = "move";
          column.classList.add("drag-over");
        });

        column.addEventListener("dragleave", event => {
          if (!column.contains(event.relatedTarget)) {
            column.classList.remove("drag-over");
          }
        });

        column.addEventListener("drop", event => {
          event.preventDefault();
          const cardId = event.dataTransfer.getData("text/plain") || draggedCardId;
          if (cardId) moveCard(cardId, column.dataset.column);
          column.classList.remove("drag-over");
        });
      });

      render();
    })();
  </script>
</body>
</html>
